{"cards": [{"node_code": "N_0f423b1b99bd6cd4", "definition": "研究斜拉桥下部结构（索塔、墩台、基础）的受力特性、设计理论、材料选择及施工技术的学科分支，重点解决塔柱与拉索连接及基础稳定性问题。", "boundary": "本节点聚焦于支撑斜拉桥上部结构并传递荷载至地基的下部实体结构。包含索塔（塔柱）的截面设计、稳定性分析、拉索锚固区构造，以及桥墩、桥台和基础的设计与施工。边界在于区分“下部结构”与“上部结构”，索塔虽高耸但作为拉索支撑点归入此处，主梁及拉索本体归入上部结构。不包含纯地质勘察或通用基础理论。", "includes": ["斜拉桥索塔（塔柱）的结构设计、稳定性分析及拉索锚固构造", "斜拉桥桥墩、桥台及桩基、承台等基础结构的设计与施工", "下部结构在施工过程中的变形控制、监测及维护加固技术"], "excludes": ["斜拉桥主梁、斜拉索及桥面系等上部结构内容", "不涉及桥梁下部结构的纯岩土工程或通用基础理论研究"], "sibling_distinctions": [{"other_code": "N_a98765411d15df3d", "rule": "本节点关注索塔、墩台及基础；兄弟节点“上部”关注主梁、斜拉索及桥面系。索塔作为拉索支撑点归入下部，主梁及拉索归入上部。"}, {"other_code": "N_cbd0813527303975", "rule": "本节点侧重下部结构的整体受力体系与宏观设计；兄弟节点“构造”侧重细部节点、连接件及材料工艺细节，若内容涉及塔柱具体钢筋布置或锚固区细部，可交叉参考，但主体设计归入本节点。"}], "cross_boundary_rule": "当索塔与主梁连接处（塔梁结合部）出现时，若主要讨论塔柱受力及锚固，归入本节点；若主要讨论主梁端部构造，归入上部结构节点。"}, {"node_code": "N_cbd0813527303975", "definition": "研究斜拉桥各组成部分（塔、梁、索）的细部构造、节点连接、材料工艺及耐久性设计的学科分支，涵盖锚固、伸缩、防水等具体实施细节。", "boundary": "本节点聚焦于斜拉桥工程中的“构造”细节，即如何将设计理论转化为可施工、可维护的具体实体。包含索塔锚固区、梁端锚固区、索梁连接、索塔连接、桥面铺装、伸缩缝、排水及防腐等细部设计。边界在于区分“构造”与“结构计算”，本节点不侧重整体受力分析，而侧重节点形式、材料匹配及施工工艺。不包含宏观结构体系选择。", "includes": ["斜拉桥索塔、主梁及拉索的锚固构造、节点连接及细部设计", "斜拉桥桥面系构造、伸缩装置、排水系统、防水及防腐措施", "斜拉桥施工中的临时构造、安装工艺及耐久性设计细节"], "excludes": ["斜拉桥整体结构体系分析、索力调整及宏观受力计算", "不涉及具体构造细节的纯材料科学或纯施工工艺理论研究"], "sibling_distinctions": [{"other_code": "N_a98765411d15df3d", "rule": "本节点关注细部构造与节点；兄弟节点“上部”关注主梁、拉索的整体结构设计与受力。若内容涉及主梁截面形式及整体刚度，归入上部；若涉及主梁端部锚固块具体尺寸及钢筋布置，归入本节点。"}, {"other_code": "N_0f423b1b99bd6cd4", "rule": "本节点关注细部构造与节点；兄弟节点“下部结构”关注索塔、墩台的整体设计与基础。若内容涉及索塔整体稳定性，归入下部；若涉及索塔锚固区具体构造，归入本节点。"}], "cross_boundary_rule": "当构造细节与结构受力紧密耦合（如锚固区应力集中分析）时，若侧重构造形式选择，归入本节点；若侧重受力机理及尺寸优化，归入对应的上部或下部结构节点。"}]}
